package com.lianxibu.site.service.jobs;
import static org.junit.jupiter.api.Assertions.*;
import com.lianxibu.site.domain.protocol.*;
import com.lianxibu.site.repository.jobs.*;
import com.lianxibu.site.repository.content.*;
import com.lianxibu.site.service.content.*;
import com.lianxibu.site.service.content.ReviewPublicationService.*;
import java.util.*;
import org.junit.jupiter.api.*;
import tools.jackson.databind.JsonNode;

class ReviewPublicationJdbcStoreTest {
 ResultJdbcStoreTest fixture;FrozenContentVersionService versions;ContentReadService admin,publicReads;ContentReviewWriteService writer;ContentReviewEvidenceService audit;ReviewPublicationJdbcStore.ValidityProof proof;
 @BeforeEach void setup(){fixture=new ResultJdbcStoreTest();fixture.fixture();install();}
 void install(){fixture.apply();fixture.jdbc.execute("ALTER TABLE article_revisions ADD validity_revision BIGINT NOT NULL DEFAULT 0");versions=new FrozenContentVersionService(new JdbcFrozenContentVersions(fixture.source));admin=new ContentReadService(new JdbcContentReads(fixture.source),fixture.tx,ContentReadService.denyUnverifiedReferences());writer=new ContentReviewWriteService(new JdbcReviewPublication(fixture.source),new GeneratedContentService(new JdbcGeneratedContents(fixture.source),fixture.clock),fixture.clock);audit=new ContentReviewEvidenceService(fixture.source,admin,versions,fixture.clock,"fictional-owner");
  proof=new ReviewPublicationJdbcStore.ValidityProof(){
   public boolean exactVersionExists(JsonNode target){if(target.path("kind").asText().equals("content_version"))return versions.find(ContentVersionKey.fromJson(target)).isPresent();if(!target.path("kind").asText().equals("article_revision"))return false;return fixture.jdbc.query("SELECT id FROM article_revisions WHERE id=?",(rs,n)->rs.getString(1),target.path("id").asText()).contains(target.path("id").asText());}
   public VersionValidityService.Validity validity(JsonNode target){if(target.path("kind").asText().equals("content_version")){String hash=JdbcResultState.sha(JdbcFrozenContentVersions.version(ContentVersionKey.fromJson(target)));if(fixture.jdbc.queryForObject("SELECT COUNT(*) FROM jobs WHERE target_type='content_version' AND target_key_hash=UNHEX(?)",Integer.class,hash)!=0)throw new IllegalStateException("unassembled ledger fixture");return new VersionValidityService.Validity(0,true,Set.of());}return fixture.jdbc.query("SELECT validity_revision,effective_valid FROM article_revisions WHERE id=?",(rs,n)->new VersionValidityService.Validity(rs.getLong(1),rs.getBoolean(2),rs.getBoolean(2)?Set.of():Set.of("fictional-invalidation-"+rs.getLong(1))),target.path("id").asText()).getFirst();}
   public void lockStableIdentity(JsonNode target){if(target.path("kind").asText().equals("content_version")){var key=ContentVersionKey.fromJson(target);assertNotNull(writer.reviewSnapshot(key.contentKind(),key.contentId()));}else assertEquals(target.path("id").asText(),fixture.jdbc.queryForObject("SELECT id FROM article_revisions WHERE id=? FOR UPDATE",String.class,target.path("id").asText()));}
  };
  publicReads=new ContentReadService(new JdbcContentReads(fixture.source),fixture.tx,new ReviewPublicationService(fixture.writes,store(null)));
 }
 ReviewPublicationJdbcStore store(ReviewPublicationJdbcStore.Command cmd){return new ReviewPublicationJdbcStore(cmd,writer,admin,audit,versions,proof);}
 ReviewPublicationService service(String op,long expected,String body,String reason){String hash=body==null?null:CanonicalJson.hash(CanonicalJson.Domain.CONTENT,CanonicalJson.parse(body));return new ReviewPublicationService(fixture.writes,store(new ReviewPublicationJdbcStore.Command(op,"report","fictional-report",expected,hash,reason)));}
 Receipt approve(long revision,String key){return service("approve",revision,null,"Fictional approval").approve("report","fictional-report",revision,fixture.action(key));}
 Receipt publish(long revision,String key){return service("publish",revision,null,"Fictional publication").publish("report","fictional-report",revision,fixture.action(key));}
 @Test void approvePublishInvalidationReversalAndReapprovalUseExactOriginalVector(){assertEquals("approved",approve(1,"fictional-approve").state());assertEquals("published",publish(2,"fictional-publish").state());assertTrue(publicReads.published("report","fictional-report").isPresent());assertEquals(1,publicReads.publishedPage("report",1,20).total());fixture.jdbc.update("UPDATE article_revisions SET validity_revision=1,effective_valid=false");assertTrue(publicReads.published("report","fictional-report").isEmpty());assertEquals("published",admin.adminCurrent("report","fictional-report").orElseThrow().state());fixture.jdbc.update("UPDATE article_revisions SET validity_revision=2,effective_valid=true");assertTrue(publicReads.published("report","fictional-report").isEmpty());approve(3,"fictional-reapprove");publish(4,"fictional-republish");assertTrue(publicReads.published("report","fictional-report").isPresent());assertEquals(1,admin.adminCurrent("report","fictional-report").orElseThrow().bodyRevision());}
 @Test void actualEditReturnsDraftAndPreservesOldVersionBeforeReapproval(){approve(1,"fictional-approve");publish(2,"fictional-publish");var old=admin.adminCurrent("report","fictional-report").orElseThrow();var version=new ContentVersionKey(old.kind(),old.id(),old.bodyRevision(),HexFormat.of().formatHex(old.bodyHashV1()),old.inputJobId());String body=ResultJdbcStoreTest.BODY.replace("Fictional text","Fictional manual edit");assertEquals("draft",service("edit",3,body,"Fictional edited body").edit("report","fictional-report",3,body,fixture.action("fictional-edit")).state());assertTrue(publicReads.published("report","fictional-report").isEmpty());assertEquals(2,admin.adminCurrent("report","fictional-report").orElseThrow().bodyRevision());assertTrue(versions.find(version).isPresent());approve(4,"fictional-edited-approve");publish(5,"fictional-edited-publish");assertTrue(publicReads.published("report","fictional-report").isPresent());assertEquals(1,fixture.sends);}
 @Test void staleCasDifferentCommandAndCrossOperationCannotReplayOriginalApproval(){var original=approve(1,"fictional-approve");assertEquals(original,approve(1,"fictional-approve"));assertThrows(Conflict.class,()->approve(1,"fictional-stale"));assertThrows(Conflict.class,()->service("approve",1,null,"Fictional different reason").approve("report","fictional-report",1,fixture.action("fictional-approve")));assertThrows(Conflict.class,()->publish(1,"fictional-approve"));assertEquals(2,admin.adminCurrent("report","fictional-report").orElseThrow().revision());}
 @Test void approvalAckLossReturnsPermanentReceiptAndDoesNotAdvanceAgain(){fixture.tx.ackLost=true;var receipt=approve(1,"fictional-approval-unknown");assertEquals(receipt,approve(1,"fictional-approval-unknown"));assertEquals(2,admin.adminCurrent("report","fictional-report").orElseThrow().revision());assertEquals(1,fixture.jdbc.queryForObject("SELECT COUNT(*) FROM jobs WHERE target_type='content_review_action'",Integer.class));}
 @Test void receiptFailureRollsBackApprovalAndNoPublicQualificationLeaks(){fixture.jdbc.execute("ALTER TABLE jobs ADD CONSTRAINT fictional_review_receipt_failure CHECK(target_type IS NULL OR target_type<>'content_review_action')");assertThrows(RuntimeException.class,()->approve(1,"fictional-failed-approval"));var row=admin.adminCurrent("report","fictional-report").orElseThrow();assertEquals("draft",row.state());assertEquals(1,row.revision());assertNull(row.reviewStampHash());assertTrue(publicReads.published("report","fictional-report").isEmpty());}
 @Test void missingFrozenInputAndUnfrozenCitationCannotAcquirePublicQualification(){String body=ResultJdbcStoreTest.BODY.replace("fictional-citation","fictional-unfrozen");assertThrows(IllegalStateException.class,()->service("edit",1,body,"Fictional invalid citation").edit("report","fictional-report",1,body,fixture.action("fictional-invalid-edit")));assertEquals(1,admin.adminCurrent("report","fictional-report").orElseThrow().revision());fixture.jdbc.update("DELETE FROM jobs WHERE purpose='input' AND part_no=0");assertThrows(RuntimeException.class,()->approve(1,"fictional-missing-input"));assertTrue(publicReads.published("report","fictional-report").isEmpty());}
}
